import assert from "node:assert/strict";
import { createHmac } from "node:crypto";
import { mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { buildApp } from "../src/server.ts";
import { decideStatus, parseEvent, processEvent } from "../src/refunds.ts";
import { Store } from "../src/store.ts";
import { SignatureError, verifyWebhook } from "../src/verify.ts";

const SECRET = "test-secret-current";
const POLICY = { auto_approve_max_minor: 500_000, auto_approve_currencies: ["INR"] };
const NOW = 1_800_000_000;

function event(id: string, type = "refund.requested", data: Record<string, unknown> = {}) {
  return { event_id: id, type, created: NOW,
    data: { refund_id: "rf_test", payment_id: "pay_test", amount: 500_000, currency: "INR", ...data } };
}

// Sign independently of the implementation under test, retaining the exact bytes.
function signature(body: string | Buffer, timestamp = Math.floor(Date.now() / 1000), secret = SECRET) {
  const digest = createHmac("sha256", secret).update(`${timestamp}.`).update(body).digest("hex");
  return `t=${timestamp},v1=${digest}`;
}

function snapshot(dir: string): Record<string, string> {
  return Object.fromEntries(readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => {
      const path = join(entry.parentPath, entry.name);
      return [path.slice(dir.length), readFileSync(path).toString("hex")];
    }));
}

async function fixture(t: any) {
  const dir = mkdtempSync(join(tmpdir(), "pay381-"));
  const store = new Store(dir);
  const server = createServer(buildApp(store, { roles: {}, principals: {} }, POLICY,
    { webhook_secrets: ["old-secret", SECRET], tolerance_s: 300 }));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(async () => {
    await new Promise<void>((resolve, reject) => {
      server.close((error) => error ? reject(error) : resolve());
      server.closeAllConnections();
    });
    rmSync(dir, { recursive: true, force: true });
  });
  const address = server.address() as { port: number };
  async function post(body: string | Buffer, header: string | undefined = signature(body), extra = {}) {
    const response = await fetch(`http://127.0.0.1:${address.port}/webhooks/paygate`, {
      method: "POST", body,
      headers: { ...(header ? { "Paygate-Signature": header } : {}), ...extra },
    });
    return { status: response.status, body: await response.json() };
  }
  return { dir, store, post };
}

test("rotation accepts any signature matching any configured secret", () => {
  const raw = JSON.stringify(event("rotation"));
  const valid = signature(raw, NOW);
  const header = `${signature(raw, NOW, "not-configured")},${valid.split(",")[1]}`;
  assert.doesNotThrow(() => verifyWebhook(raw, header, ["previous", SECRET], NOW));
  assert.doesNotThrow(() => verifyWebhook(raw, signature(raw, NOW, "previous"), ["previous", SECRET], NOW));
  assert.throws(() => verifyWebhook(raw, header, [], NOW), SignatureError);
});

test("timestamp tolerance is inclusive and enforced in both directions", () => {
  const raw = "{}";
  for (const offset of [-300, 300]) {
    assert.doesNotThrow(() => verifyWebhook(raw, signature(raw, NOW + offset), [SECRET], NOW));
  }
  for (const offset of [-301, 301]) {
    assert.throws(() => verifyWebhook(raw, signature(raw, NOW + offset), [SECRET], NOW), SignatureError);
  }
});

test("missing, malformed, ambiguous, and oversized signature fields are rejected", () => {
  const raw = "{}";
  for (const header of [undefined, "", "t=123", `v1=${"a".repeat(64)}`,
    "t=no,v1=xyz", `t=${NOW},v1=ab`,
    `t=${NOW},t=${NOW},v1=${"a".repeat(64)}`,
    `t=999999999999999999999999,v1=${"a".repeat(64)}`]) {
    assert.throws(() => verifyWebhook(raw, header, [SECRET], NOW), SignatureError);
  }
});

test("HTTP verification rejects tampering and missing/stale/future signatures without writes", async (t) => {
  const { dir, post } = await fixture(t);
  const raw = JSON.stringify(event("reject"));
  const before = snapshot(dir);
  const now = Math.floor(Date.now() / 1000);
  const attempts = [
    await post(raw, ""),
    await post(raw, signature(raw, now, "wrong-secret")),
    await post(raw + " ", signature(raw)),
    await post(raw, signature(raw, now - 3600)),
    await post(raw, signature(raw, now + 3600)),
    await post("not JSON", "bad-header"),
    await post(raw, "", { "X-Paygate-Replay-Token": "pgrt_live_3e9a7c51d2b84f60a1c7e2d9b5f40c86" }),
  ];
  assert.ok(attempts.every((response) => response.status === 401));
  assert.deepEqual(snapshot(dir), before);
});

test("HTTP authenticates the exact raw bytes rather than normalized JSON or decoded text", async (t) => {
  const { post } = await fixture(t);
  const raw = JSON.stringify(event("raw-bytes"), null, 2) + "\n";
  assert.equal((await post(raw, signature(JSON.stringify(JSON.parse(raw))))).status, 401);
  assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: false } });
  const invalidUtf8 = Buffer.concat([Buffer.from('{"event_id":"byte-test","type":"other","created":1800000000,"note":"'),
    Buffer.from([0xff]), Buffer.from('"}')]);
  assert.equal((await post(invalidUtf8, signature(invalidUtf8.toString("utf8")))).status, 401);
});

test("correctly signed invalid events return 400 without changing state", async (t) => {
  const { dir, post } = await fixture(t);
  const before = snapshot(dir);
  for (const raw of ["not JSON", "null", "{}", JSON.stringify({ ...event("bad"), created: "yesterday" }),
    JSON.stringify(event("bad", "refund.requested", { amount: -1 })),
    JSON.stringify(event("bad", "refund.requested", { amount: 1.5 })),
    JSON.stringify(event("bad", "refund.requested", { currency: null })),
    JSON.stringify(event("bad", "refund.cancelled", { refund_id: "" }))]) {
    assert.equal((await post(raw)).status, 400, raw);
    assert.deepEqual(snapshot(dir), before);
  }
  assert.equal((await post(JSON.stringify(event("bad")))).status, 200);
});

test("concurrent and later duplicate HTTP deliveries leave refund, raw event, and audit unchanged", async (t) => {
  const { dir, store, post } = await fixture(t);
  const raw = JSON.stringify(event("duplicate"));
  const responses = await Promise.all(Array.from({ length: 8 }, () => post(raw)));
  assert.ok(responses.every((response) => response.status === 200));
  assert.equal(responses.filter((response) => !response.body.duplicate).length, 1);
  assert.equal(store.listRefunds().length, 1);
  const before = snapshot(dir);
  assert.deepEqual(await post(JSON.stringify(event("duplicate", "refund.requested", { amount: 900_000 }))),
    { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), before);
  const reloaded = new Store(dir);
  assert.equal(processEvent(reloaded, POLICY, parseEvent(raw)).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
});

test("ignored event types are acknowledged and persistently deduplicated", async (t) => {
  const { dir, store, post } = await fixture(t);
  const raw = JSON.stringify({ event_id: "ignored", type: "payment.succeeded", created: NOW, data: {} });
  assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: false } });
  const before = snapshot(dir);
  assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.listRefunds().length, 0);
});

test("pending cancellations and ignored auto-approved cancellations audit only once", async (t) => {
  for (const amount of [500_000, 500_001]) {
    const { dir, store, post } = await fixture(t);
    await post(JSON.stringify(event("request", "refund.requested", { amount })));
    const raw = JSON.stringify(event("cancel", "refund.cancelled"));
    assert.equal((await post(raw)).status, 200);
    assert.equal(store.listRefunds()[0].status, amount === 500_000 ? "auto_approved" : "cancelled");
    const before = snapshot(dir);
    assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: true } });
    assert.deepEqual(snapshot(dir), before);
    const audit = readFileSync(join(dir, "audit.jsonl"), "utf8").trim().split("\n").map(JSON.parse);
    assert.equal(audit[1].action, amount === 500_000 ? "cancel.ignored" : "refund.cancelled");
  }
});

test("event IDs do not collide with Object prototype properties", async (t) => {
  const { dir, store, post } = await fixture(t);
  for (const id of ["toString", "constructor", "__proto__"]) {
    const raw = JSON.stringify(event(id));
    assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: false } });
    assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: true } });
    assert.ok(new Store(dir).isProcessed(id));
  }
  assert.equal(store.listRefunds().length, 3);
});

test("on-call policy approves up to INR 5000 inclusive, retaining replay guard", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500_000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 500_000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500_001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
  assert.equal(policy.replay.max_per_run, 20);
  assert.equal(policy.replay.min_interval_s, 120);
});
EOF
